{"database": "prod-ops-1", "statement": "BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- CHG-7714: add outage window tracking to feeder_events
ALTER TABLE feeder_events
  ADD COLUMN IF NOT EXISTS outage_id bigint,
  ADD COLUMN IF NOT EXISTS restored_at timestamptz,
  ADD COLUMN IF NOT EXISTS cause_code text;

CREATE TABLE IF NOT EXISTS outage_windows (
  outage_id    bigserial PRIMARY KEY,
  feeder_id    integer NOT NULL REFERENCES feeders(feeder_id),
  started_at   timestamptz NOT NULL,
  restored_at  timestamptz,
  customers_affected integer,
  cause_code   text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  CHECK (restored_at IS NULL OR restored_at >= started_at)
);

CREATE INDEX IF NOT EXISTS outage_windows_feeder_started_idx
  ON outage_windows (feeder_id, started_at DESC);

ALTER TABLE feeder_events
  ADD CONSTRAINT feeder_events_outage_fk
  FOREIGN KEY (outage_id) REFERENCES outage_windows(outage_id) NOT VALID;

-- backfill the last 90 days from the existing trip/restore event pairs
INSERT INTO outage_windows (feeder_id, started_at, restored_at, customers_affected)
SELECT t.feeder_id, t.occurred_at, min(r.occurred_at), max(t.customers_out)
FROM feeder_events t
LEFT JOIN feeder_events r
  ON r.feeder_id = t.feeder_id
 AND r.event_type = 'RESTORE'
 AND r.occurred_at > t.occurred_at
WHERE t.event_type = 'TRIP'
  AND t.occurred_at >= now() - interval '90 days'
GROUP BY t.feeder_id, t.occurred_at;

COMMIT;
", "change_ticket": "CHG-7714"}

